CREATE TABLE `produits` (
  `id` int(11) NOT NULL,
  `identifiant_interne` varchar(20) DEFAULT NULL,
  `nom` varchar(255) NOT NULL,
  `description` text NOT NULL,
  `nom_fournisseur` varchar(255) DEFAULT NULL COMMENT 'Nom ou raison sociale du fournisseur (optionnel)',
  `fournisseur_id` int(11) DEFAULT NULL,
  `prix` decimal(10,2) NOT NULL,
  `prix_promotion` decimal(10,2) DEFAULT NULL,
  `stock` int(11) NOT NULL DEFAULT 0,
  `categorie_id` int(11) NOT NULL,
  `marque_id` int(10) UNSIGNED DEFAULT NULL,
  `reference_fournisseur` varchar(120) DEFAULT NULL,
  `stock_article_id` int(11) DEFAULT NULL,
  `image_principale` varchar(255) DEFAULT NULL,
  `image_etiquette_fpl` varchar(255) DEFAULT NULL COMMENT 'Chemin relatif upload/ ex. produits/xxx.jpg pour etiquette FPL',
  `images` text DEFAULT NULL,
  `poids` varchar(50) DEFAULT NULL,
  `unite` varchar(20) NOT NULL DEFAULT 'unité',
  `etage` varchar(50) DEFAULT NULL COMMENT 'Étage entrepôt / magasin',
  `numero_rayon` varchar(50) DEFAULT NULL COMMENT 'Numéro ou code rayon',
  `allee` tinyint(3) UNSIGNED DEFAULT NULL COMMENT 'Allée entrepôt (1-10)',
  `zone_emplacement` tinyint(3) UNSIGNED DEFAULT NULL COMMENT 'Zone entrepôt (1-10)',
  `position_emplacement` tinyint(3) UNSIGNED DEFAULT NULL COMMENT 'Position dans le rayon (1-10)',
  `barre_rayon` tinyint(3) UNSIGNED DEFAULT NULL COMMENT 'Barre / étagère du rayon (1-10)',
  `entrepot_position_id` int(10) UNSIGNED DEFAULT NULL,
  `entrepot_noeud_id` int(10) UNSIGNED DEFAULT NULL,
  `date_creation` datetime NOT NULL DEFAULT current_timestamp(),
  `date_modification` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `statut` enum('actif','inactif','rupture_stock') NOT NULL DEFAULT 'actif',
  `couleurs` varchar(255) DEFAULT NULL COMMENT 'Couleurs disponibles (ex: Rouge, Bleu, Vert)',
  `taille` varchar(255) DEFAULT NULL COMMENT 'Tailles disponibles (ex: S, M, L ou 21cm, 14.8cm)',
  `admin_createur_id` int(11) DEFAULT NULL,
  `admin_dernier_modificateur_id` int(11) DEFAULT NULL,
  `prix_achat` decimal(10,2) DEFAULT NULL,
  `sous_categorie_id` int(11) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

